/**
 * Design notes (docs/QUEST_PLAN.md 4.6 item 1, docs/WORLD_PLAN.md 4.0.4): every built pass W map source opens with
 * three labelled comment lines, `Concept:`, `Distinct:` (at least 2 features no classic version of the place has,
 * separated by `;` or `,`) and `Topology:` (the stair and boss graph), in that order, in its leading comment block
 * (after a `GENERATED by` header, if any). A stub is pending (a failure with QUEST_STRICT=1).
 */
import { describe, expect, it } from 'vitest';
import { canonRows, designNote, isBuilt, sourceText, STRICT } from './questMaps.js';

describe('designNotes: the rule', () => {
  const good = ['# GENERATED by layouts/marsh.py - edit the script', '# Concept: a drowned fen of peat islands',
    '# Distinct: peat that burns underfoot; a heron rookery', '# Topology: B1 -> B2 (2 stairs) -> B3 boss', 'id: x'].join('\n');

  it('accepts the three labelled lines after a generated header', () => {
    expect(designNote(good)).toEqual({ errors: [], note: { Concept: 'a drowned fen of peat islands',
      Distinct: 'peat that burns underfoot; a heron rookery', Topology: 'B1 -> B2 (2 stairs) -> B3 boss' } });
  });

  it('RED: a missing line, a single distinct feature, the wrong order, a note below the map', () => {
    expect(designNote(good.replace('# Topology: B1 -> B2 (2 stairs) -> B3 boss\n', '')).errors).toEqual(['no Topology: line']);
    expect(designNote(good.replace('; a heron rookery', '')).errors).toEqual(['Distinct: names fewer than 2 features']);
    const swapped = good.replace('# Concept: a drowned fen of peat islands\n', '').replace('id: x', '') + '';
    expect(designNote(`# Topology: B1\n${swapped}`).errors).toContain('no Concept: line');
    expect(designNote(`id: x\n${good}`).errors).toHaveLength(3);
    const order = ['# Distinct: a; b', '# Concept: c', '# Topology: B1 boss'].join('\n');
    expect(designNote(order).errors).toEqual(['Distinct: out of order']);
  });
});

describe('designNotes: the pass W maps', () => {
  const rows = canonRows();
  const built = rows.filter((r) => isBuilt(r.id));

  it('the canon lists every pass W map id (136; pass CD: bahamut-cave and -lair retired into cardia-deep)', () => {
    expect(rows.length).toBe(136);
  });

  it(`every built map has its design note (${built.length} built, ${rows.length - built.length} stubs pending)`, () => {
    const bad = built.map((r) => ({ id: r.id, errors: designNote(sourceText(r.id)!).errors })).filter((x) => x.errors.length);
    expect(bad).toEqual([]);
    if (STRICT) expect(rows.filter((r) => !isBuilt(r.id)).map((r) => r.id)).toEqual([]);
  });
});
